import { Controller, Get, Post, Put, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const USE_STATUSES = ['사용', '미사용'];

type Body = Record<string, unknown>;

function isBlank(v: unknown): boolean {
  return v === undefined || v === null || v === '';
}

function invalid(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function textOf(v: unknown, max: number, label: string): string | null {
  if (isBlank(v)) {
    return null;
  }
  if (typeof v !== 'string') {
    throw invalid(label + ' 형식이 올바르지 않습니다.');
  }
  if (v.length > max) {
    throw invalid(label + '은(는) ' + max + '자 이하로 입력해 주세요.');
  }
  return v;
}

function flagOf(v: unknown, label: string): boolean {
  if (typeof v === 'boolean') {
    return v;
  }
  if (v === 'true') {
    return true;
  }
  if (v === 'false') {
    return false;
  }
  throw invalid(label + ' 형식이 올바르지 않습니다.');
}

function idOf(v: unknown, label: string): string {
  const s = typeof v === 'number' ? String(v) : v;
  if (typeof s !== 'string' || !/^[0-9]{1,18}$/.test(s)) {
    throw invalid(label + '은(는) 숫자여야 합니다.');
  }
  return s;
}

// 등록·수정 공통: 필수 값 누락은 422, 형식 오류는 400
function parseBody(data: Body) {
  const required: [string, string][] = [
    ['evidenceType', '증빙유형'],
    ['evidenceItemName', '증빙항목명'],
    ['collectEnabled', '자료수집 사용 여부'],
    ['autoJournalEnabled', '자동분개 사용 여부'],
    ['accountSubjectId', '분개 계정과목'],
  ];
  const missing = required.filter(([key]) => isBlank(data[key])).map(([, label]) => label);
  if (missing.length > 0) {
    throw new ApiError(422, 'REQUIRED_SETTING_MISSING', '필수 설정값이 누락되었습니다: ' + missing.join(', '));
  }
  const useStatus = textOf(data['useStatus'], 10, '사용 여부');
  if (useStatus !== null && !USE_STATUSES.includes(useStatus)) {
    throw invalid('사용 여부는 사용 또는 미사용이어야 합니다.');
  }
  return {
    evidenceType: textOf(data['evidenceType'], 50, '증빙유형'),
    evidenceItemName: textOf(data['evidenceItemName'], 200, '증빙항목명'),
    collectEnabled: flagOf(data['collectEnabled'], '자료수집 사용 여부'),
    autoJournalEnabled: flagOf(data['autoJournalEnabled'], '자동분개 사용 여부'),
    collectCondition: textOf(data['collectCondition'], 1000, '자료수집 조건'),
    journalCondition: textOf(data['journalCondition'], 1000, '자동분개 조건'),
    accountSubjectId: idOf(data['accountSubjectId'], '분개 계정과목'),
    useStatus,
  };
}

@Controller('api/v1')
export class FnSfr00701Controller {
  @Get('/auto-journal-settings')
  async listAutoJournalSettings(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const evidenceType = textOf(query['evidenceType'], 50, '증빙유형');
    const useStatus = textOf(query['useStatus'], 10, '사용 여부');
    if (useStatus !== null && !USE_STATUSES.includes(useStatus)) {
      throw invalid('사용 여부는 사용 또는 미사용이어야 합니다.');
    }
    const pageText = isBlank(query['page']) ? '0' : String(query['page']);
    const sizeText = isBlank(query['size']) ? String(DEFAULT_SIZE) : String(query['size']);
    if (!/^[0-9]{1,9}$/.test(pageText) || !/^[0-9]{1,9}$/.test(sizeText)) {
      throw invalid('page와 size는 0 이상의 숫자여야 합니다.');
    }
    const page = Number(pageText);
    const size = Math.min(Math.max(Number(sizeText), 1), MAX_SIZE);
    return transaction(async (db) => {
      const filter = ' WHERE (CAST(:evidenceType AS text) IS NULL OR evidence_type = CAST(:evidenceType AS text))'
        + ' AND (CAST(:useStatus AS text) IS NULL OR use_status = CAST(:useStatus AS text))';
      const countRows = await db.query(
        'SELECT COUNT(*) AS "total" FROM auto_journal_setting' + filter,
        { evidenceType, useStatus },
      );
      const items = await db.query(
        'SELECT auto_journal_setting_id AS "autoJournalSettingId",'
        + ' evidence_type AS "evidenceType",'
        + ' evidence_item_name AS "evidenceItemName",'
        + ' collect_enabled AS "collectEnabled",'
        + ' auto_journal_enabled AS "autoJournalEnabled",'
        + ' collect_condition AS "collectCondition",'
        + ' journal_condition AS "journalCondition",'
        + ' account_subject_id AS "accountSubjectId",'
        + ' use_status AS "useStatus"'
        + ' FROM auto_journal_setting' + filter
        + ' ORDER BY auto_journal_setting_id'
        + ' LIMIT CAST(:size AS int) OFFSET CAST(:offset AS int)',
        { evidenceType, useStatus, size, offset: page * size },
      );
      return { items, page, size, total: Number(countRows[0]['total']) };
    });
  }

  @Post('/auto-journal-settings')
  @HttpCode(200)
  async createAutoJournalSetting(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const p = parseBody(data);
    return transaction(async (db) => {
      const subjects = await db.query(
        'SELECT account_subject_id FROM account_subject WHERE account_subject_id = CAST(:accountSubjectId AS bigint)',
        { accountSubjectId: p.accountSubjectId },
      );
      if (subjects.length === 0) {
        throw new ApiError(404, 'ACCOUNT_SUBJECT_NOT_FOUND', '지정한 계정과목을 찾을 수 없습니다.');
      }
      const dup = await db.query(
        'SELECT auto_journal_setting_id FROM auto_journal_setting WHERE evidence_type = :evidenceType AND evidence_item_name = :evidenceItemName',
        { evidenceType: p.evidenceType, evidenceItemName: p.evidenceItemName },
      );
      if (dup.length > 0) {
        throw invalid('같은 증빙유형과 증빙항목명의 설정이 이미 있습니다.');
      }
      // 가정: 사용 여부를 보내지 않으면 '사용'으로 시작한다
      const rows = await db.query(
        'INSERT INTO auto_journal_setting (evidence_type, evidence_item_name, collect_enabled, auto_journal_enabled,'
        + ' collect_condition, journal_condition, account_subject_id, use_status, created_at, updated_at)'
        + ' VALUES (:evidenceType, :evidenceItemName, :collectEnabled, :autoJournalEnabled,'
        + ' :collectCondition, :journalCondition, CAST(:accountSubjectId AS bigint), COALESCE(CAST(:useStatus AS text), :defaultStatus), now(), now())'
        + ' RETURNING auto_journal_setting_id AS "autoJournalSettingId"',
        { ...p, defaultStatus: '사용' },
      );
      return { autoJournalSettingId: Number(rows[0]['autoJournalSettingId']) };
    });
  }

  @Put('/auto-journal-settings/:autoJournalSettingId')
  async updateAutoJournalSetting(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = idOf(req.params['autoJournalSettingId'], '설정 ID');
    const data = checks.inputOf(req.body);
    const p = parseBody(data);
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT auto_journal_setting_id FROM auto_journal_setting WHERE auto_journal_setting_id = CAST(:id AS bigint)',
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'AUTO_JOURNAL_SETTING_NOT_FOUND', '수정할 자동전표 설정을 찾을 수 없습니다.');
      }
      const subjects = await db.query(
        'SELECT account_subject_id FROM account_subject WHERE account_subject_id = CAST(:accountSubjectId AS bigint)',
        { accountSubjectId: p.accountSubjectId },
      );
      if (subjects.length === 0) {
        throw new ApiError(404, 'ACCOUNT_SUBJECT_NOT_FOUND', '지정한 계정과목을 찾을 수 없습니다.');
      }
      const dup = await db.query(
        'SELECT auto_journal_setting_id FROM auto_journal_setting WHERE evidence_type = :evidenceType AND evidence_item_name = :evidenceItemName'
        + ' AND auto_journal_setting_id <> CAST(:id AS bigint)',
        { evidenceType: p.evidenceType, evidenceItemName: p.evidenceItemName, id },
      );
      if (dup.length > 0) {
        throw invalid('같은 증빙유형과 증빙항목명의 설정이 이미 있습니다.');
      }
      await db.execute(
        'UPDATE auto_journal_setting SET evidence_type = :evidenceType, evidence_item_name = :evidenceItemName,'
        + ' collect_enabled = :collectEnabled, auto_journal_enabled = :autoJournalEnabled,'
        + ' collect_condition = :collectCondition, journal_condition = :journalCondition,'
        + ' account_subject_id = CAST(:accountSubjectId AS bigint),'
        + ' use_status = COALESCE(CAST(:useStatus AS text), use_status), updated_at = now()'
        + ' WHERE auto_journal_setting_id = CAST(:id AS bigint)',
        { ...p, id },
      );
      return { autoJournalSettingId: Number(id) };
    });
  }
}

