import { useState } from 'react';
import { call, useData, Filters, Band, DataTable, Pager, Drawer, Form, Field, TextInput, Select, LookupSelect, RefName, Badge, ErrorText } from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 20;
const STATUS_OPTIONS: [string, string][] = [['사용', '사용'], ['미사용', '미사용']];
const FLAG_OPTIONS: [string, string][] = [['true', '사용'], ['false', '미사용']];

const EMPTY_FORM: Row = {
  evidenceType: '',
  evidenceItemName: '',
  collectEnabled: 'true',
  autoJournalEnabled: 'true',
  collectCondition: '',
  journalCondition: '',
  accountSubjectId: '',
  useStatus: '사용',
};

export default function FnSfr00701Page({ role, notify }: PageProps) {
  const [evidenceType, setEvidenceType] = useState('');
  const [useStatus, setUseStatus] = useState('');
  const [applied, setApplied] = useState<Row>({});
  const [pageNo, setPageNo] = useState(0);
  const [editing, setEditing] = useState<'new' | Row | null>(null);
  const [form, setForm] = useState<Row>(EMPTY_FORM);

  const { data, error, loading, reload } = useData<Page>(
    () => call<Page>('GET', '/auto-journal-settings', role, undefined, { ...applied, page: pageNo, size: SIZE }),
    [applied, pageNo],
  );

  const setField = (key: string, value: unknown) => setForm({ ...form, [key]: value });

  const search = () => {
    setPageNo(0);
    setApplied({ evidenceType, useStatus });
  };

  const reset = () => {
    setEvidenceType('');
    setUseStatus('');
    setPageNo(0);
    setApplied({});
  };

  const openNew = () => {
    setForm(EMPTY_FORM);
    setEditing('new');
  };

  const openEdit = (row: Row) => {
    setForm({
      evidenceType: row.evidenceType ?? '',
      evidenceItemName: row.evidenceItemName ?? '',
      collectEnabled: String(row.collectEnabled),
      autoJournalEnabled: String(row.autoJournalEnabled),
      collectCondition: row.collectCondition ?? '',
      journalCondition: row.journalCondition ?? '',
      accountSubjectId: row.accountSubjectId ?? '',
      useStatus: row.useStatus ?? '사용',
    });
    setEditing(row);
  };

  const submit = async () => {
    const missing: string[] = [];
    if (!String(form.evidenceType ?? '').trim()) missing.push('증빙유형');
    if (!String(form.evidenceItemName ?? '').trim()) missing.push('증빙항목명');
    if (form.accountSubjectId === '' || form.accountSubjectId === undefined) missing.push('분개 계정과목');
    if (missing.length > 0) {
      throw new Error('다음 항목을 입력해 주세요: ' + missing.join(', '));
    }
    const body: Row = {
      evidenceType: String(form.evidenceType).trim(),
      evidenceItemName: String(form.evidenceItemName).trim(),
      collectEnabled: form.collectEnabled === 'true',
      autoJournalEnabled: form.autoJournalEnabled === 'true',
      collectCondition: form.collectCondition,
      journalCondition: form.journalCondition,
      accountSubjectId: form.accountSubjectId,
      useStatus: form.useStatus,
    };
    if (editing === 'new') {
      await call('POST', '/auto-journal-settings', role, body);
      notify('자동전표 설정을 등록했습니다.');
    } else if (editing) {
      await call('PUT', '/auto-journal-settings/' + String(editing.autoJournalSettingId), role, body);
      notify('자동전표 설정을 수정했습니다.');
    }
    setEditing(null);
    reload();
  };

  const rows = data?.items ?? [];

  return (
    <div>
      <h1>자동전표 증빙설정</h1>
      <Filters onSearch={search} onReset={reset}>
        <Field label="증빙유형">
          <TextInput value={evidenceType} onChange={setEvidenceType} />
        </Field>
        <Field label="사용 여부">
          <Select value={useStatus} onChange={setUseStatus} options={STATUS_OPTIONS} placeholder="전체" />
        </Field>
      </Filters>
      <Band total={data?.total}>
        <button onClick={openNew}>설정 등록</button>
      </Band>
      {error ? <ErrorText text={error} /> : null}
      <DataTable
        columns={[
          { key: 'evidenceType', label: '증빙유형' },
          { key: 'evidenceItemName', label: '증빙항목명' },
          {
            key: 'accountSubjectId',
            label: '분개 계정과목',
            render: (row) => <RefName table="account_subject" role={role} value={row.accountSubjectId} />,
          },
          { key: 'useStatus', label: '사용 여부', render: (row) => <Badge value={row.useStatus} /> },
          {
            key: 'actions',
            label: '처리',
            render: (row) => (
              <button className="ghost" onClick={() => openEdit(row)}>수정</button>
            ),
          },
        ]}
        rows={rows}
        empty={loading ? '불러오는 중입니다.' : '아직 등록한 설정이 없습니다. 설정 등록 버튼으로 증빙항목을 추가해 주세요.'}
      />
      <Pager page={data?.page ?? 0} size={SIZE} total={data?.total ?? 0} onPage={setPageNo} />
      {editing ? (
        <Drawer title={editing === 'new' ? '자동전표 설정 등록' : '자동전표 설정 수정'} onClose={() => setEditing(null)}>
          <Form onSubmit={submit} submit={editing === 'new' ? '등록' : '저장'}>
            <Field label="증빙유형" required>
              <TextInput value={form.evidenceType} onChange={(v) => setField('evidenceType', v)} placeholder="예: 통장, 카드, 현금영수증, 전자세금계산서" />
            </Field>
            <Field label="증빙항목명" required>
              <TextInput value={form.evidenceItemName} onChange={(v) => setField('evidenceItemName', v)} />
            </Field>
            <Field label="자료수집 사용 여부" required>
              <Select value={form.collectEnabled} onChange={(v) => setField('collectEnabled', v)} options={FLAG_OPTIONS} />
            </Field>
            <Field label="자동분개 사용 여부" required>
              <Select value={form.autoJournalEnabled} onChange={(v) => setField('autoJournalEnabled', v)} options={FLAG_OPTIONS} />
            </Field>
            <Field label="자료수집 조건" wide>
              <TextInput multiline value={form.collectCondition} onChange={(v) => setField('collectCondition', v)} />
            </Field>
            <Field label="자동분개 조건" wide>
              <TextInput multiline value={form.journalCondition} onChange={(v) => setField('journalCondition', v)} />
            </Field>
            <Field label="분개 계정과목" required>
              <LookupSelect table="account_subject" role={role} value={form.accountSubjectId} onChange={(v) => setField('accountSubjectId', v)} />
            </Field>
            <Field label="사용 여부" hint="미사용으로 두면 자료수집과 자동분개 대상에서 제외됩니다.">
              <Select value={form.useStatus} onChange={(v) => setField('useStatus', v)} options={STATUS_OPTIONS} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
